// Stage 1: corte gratuito em codigo. Mata a maior parte antes de gastar token de LLM.
// Rubrica gerada de prompts/scoring.md por build_workflow.py -- NAO editar aqui.
const NL = String.fromCharCode(10);
const PISO_FIXO = 50;
const PISO_HORA = 20;
const MAX_PROPOSTAS = 25;
const LIMIAR = 7;
const BLACKLIST = ['screen share', 'screenshare', 'share your screen', 'loom', 'webcam', 'video call', 'zoom call', 'on camera', 'face to face', 'record a video', 'screen recording'];
// Corte gratuito de PRESENCA: o que se compra e disponibilidade, nao artefato.
// Mata isso aqui em vez de gastar $0.026 pro LLM chegar na mesma conclusao.
const PRESENCA = ['virtual assistant', 'customer support agent', 'support agent', 'live chat agent', 'hours per week', 'hrs per week', 'hours/week', 'full-time position', 'full time position', 'join our team', 'ongoing support', 'daily standup', 'work our hours', 'your own hours are', 'answer phones', 'cold calling', 'appointment setter', 'data entry clerk', 'moderator'];

const RUBRICA = [
    "Você avalia uma vaga de freelancer. Quem vai executar é um desenvolvedor que trabalha com",
    "assistência de IA para código: ele produz o trabalho rápido, mas precisa entregar um",
    "ARTEFATO — não pode vender presença nem disponibilidade de horário.",
    "",
    "## A pergunta central",
    "O que o cliente recebe no final é uma COISA (site, repositório, script, sistema configurado,",
    "planilha, documento, campanha montada, integração funcionando)?",
    "→ elegível, qualquer área.",
    "",
    "Ou o que ele está comprando é ALGUÉM DISPONÍVEL (atendente, assistente virtual, plantão,",
    "moderador, \"20h por semana\", presença em reuniões recorrentes, turno)?",
    "→ inelegível, mesmo que pague bem.",
    "",
    "Atenção à pegadinha: \"construir um sistema de atendimento ao cliente\" é artefato (elegível).",
    "\"Ser o atendente de suporte\" é presença (inelegível). O título engana; leia o entregável.",
    "",
    "## O que ele consegue entregar (amplo de propósito)",
    "Sites e landing pages, front-end, HTML/CSS/JS, WordPress; scripts e ferramentas em Python ou",
    "JavaScript; integração entre sistemas via API; automação de processo (n8n, Make, Zapier);",
    "scraping e pipeline de dados; agentes de IA e integração de LLM; bots; limpeza e transformação",
    "de dados; planilhas e dashboards; documentação técnica; configuração de campanha e de",
    "ferramenta de marketing; migração de dados entre plataformas.",
    "",
    "Prova pública que ele pode citar: site próprio publicado com 4 projetos de exemplo, e 7",
    "automações rodando em produção (prospecção B2B ponta a ponta, classificação de email por LLM,",
    "webhooks de pagamento com verificação de assinatura HMAC testada, digest diário, vigia de uptime).",
    "",
    "## O que ele NÃO entrega",
    "Design gráfico original (logo, ilustração, identidade visual), edição de vídeo, locução,",
    "tradução humana certificada, app mobile nativo, e qualquer coisa que exija credencial",
    "profissional (contábil, jurídica, médica).",
    "",
    "## Restrição rígida",
    "Ele não faz webcam, screen share, gravação da própria tela, nem call com vídeo.",
    "",
    "## Como pontuar (score 1–10) — comece em 5",
    "",
    "SOMA",
    "+2  o entregável é claramente um artefato definido, com critério de \"pronto\" verificável",
    "+2  o escopo está descrito com precisão suficiente pra estimar o trabalho sem perguntar",
    "+1  o orçamento paga bem as horas estimadas (use ~$40/h como referência de valor do tempo dele)",
    "+1  está no núcleo comprovado dele (automação, integração de API, site, scraping, LLM)",
    "+1  o cliente tem histórico de pagamento na plataforma (já gastou, tem review)",
    "+1  poucas propostas ainda (ele ainda é lido)",
    "",
    "SUBTRAI",
    "-4  o que se compra é presença/disponibilidade e não artefato",
    "-3  exige webcam, screen share, gravação de tela, ou call com vídeo",
    "-3  sugere pagamento fora da plataforma, ou pede trabalho de teste não pago",
    "-3  precisa de credencial profissional, ou é design gráfico original / vídeo / app nativo",
    "-2  a descrição é vaga ao ponto de não dar pra saber o que a pessoa quer",
    "-2  orçamento irrealista pro escopo pedido",
    "-2  muitas propostas já enviadas (chegou tarde, cliente já fez shortlist)",
    "-1  exige domínio profundo de plataforma com ecossistema próprio de especialistas",
    "    (Shopify/Liquid, GoHighLevel, Salesforce, HubSpot nativo) — ele entrega, mas entra",
    "    como candidato mais fraco contra quem tem 20 projetos naquela plataforma",
    "",
    "## Regras rígidas (sobrepõem o score)",
    "- Exigência de webcam/screen share/vídeo → recommendation = \"skip\".",
    "- Pagamento fora da plataforma → recommendation = \"skip\" e red flag explícita.",
    "- Entregável é presença e não artefato → recommendation = \"skip\".",
    "- recommendation = \"apply\" exige score >= {{limiar}}.",
    "  ({{limiar}} é 7 onde candidatura custa dinheiro, 5 onde a proposta é grátis.)",
    "",
    "## Vaga",
    "{{vaga}}",
    "",
    "Responda SOMENTE com JSON válido, sem markdown, sem texto antes ou depois:",
    "",
    "{",
    "  \"score\": <int 1-10>,",
    "  \"recommendation\": \"apply\" | \"skip\",",
    "  \"entregavel\": \"<o que o cliente recebe, em 6 palavras>\",",
    "  \"tipo\": \"artefato\" | \"presenca\",",
    "  \"area\": \"<site | automacao | integracao | dados | llm | script | marketing | outro>\",",
    "  \"complexity\": \"low\" | \"medium\" | \"high\",",
    "  \"estimated_hours\": <int>,",
    "  \"budget_realistic\": <bool>,",
    "  \"red_flags\": [<string>],",
    "  \"why\": \"<uma frase, máx 20 palavras, em português>\",",
    "  \"angle\": \"<se apply: a observação concreta sobre O PROBLEMA DELE que a proposta deve abrir. Se skip: string vazia>\"",
    "}"
  ].join(NL);

const out = [];
const cortadas = [];

for (const item of $input.all()) {
  const j = item.json || {};
  if (!j.jobId) { continue; }

  const desc = String(j.description || '');
  const dlow = desc.toLowerCase();
  const appl = Number(j.totalApplicants || 0);
  const fixo = j.budgetAmount ? Number(j.budgetAmount) : null;
  const hmax = j.hourlyBudgetMax ? Number(j.hourlyBudgetMax) : null;

  let corte = null;
  if (!j.clientPaymentVerified) { corte = 'pagamento nao verificado'; }
  else if (appl > MAX_PROPOSTAS) { corte = 'tarde demais: ' + appl + ' propostas'; }
  else if (fixo !== null && fixo < PISO_FIXO) { corte = 'fixo $' + fixo + ' abaixo do piso'; }
  else if (hmax !== null && hmax < PISO_HORA) { corte = 'hourly $' + hmax + ' abaixo do piso'; }
  else {
    const kw = BLACKLIST.find(function (k) { return dlow.indexOf(k) !== -1; });
    if (kw) { corte = 'blacklist: ' + kw; }
    else {
      const pk = PRESENCA.find(function (k) { return dlow.indexOf(k) !== -1; });
      if (pk) { corte = 'presenca, nao artefato: ' + pk; }
    }
  }

  if (corte) { cortadas.push({ title: j.title, motivo: corte }); continue; }

  const pub = j.publishTime ? new Date(j.publishTime) : null;
  const idade = pub ? Math.round((Date.now() - pub.getTime()) / 60000) : -1;

  let orcamento = 'nao informado';
  if (fixo !== null) { orcamento = '$' + fixo + ' fixo'; }
  else if (j.hourlyBudgetMin || hmax) { orcamento = '$' + (j.hourlyBudgetMin || '?') + '-$' + (hmax || '?') + '/hr'; }

  const vaga = [
    'Plataforma: Upwork (candidatura custa Connects)',
    'Titulo: ' + String(j.title || ''),
    'Tipo: ' + String(j.jobType || '') + ' | Orcamento: ' + orcamento,
    'Nivel pedido: ' + String(j.experienceLevel || '') + ' | Duracao: ' + String(j.engagementDuration || ''),
    'Skills marcadas: ' + (Array.isArray(j.skills) ? j.skills.join(', ') : ''),
    'Publicada ha: ' + idade + ' minutos',
    'Propostas ja enviadas: ' + appl,
    'Cliente: ' + String(j.clientCountry || '') + ' | pagamento verificado: ' + String(j.clientPaymentVerified) + ' | ja gastou: $' + String(j.clientTotalSpent || 0) + ' | rating: ' + String(j.clientRating || 0) + ' (' + String(j.clientReviewCount || 0) + ' reviews)',
    '',
    'Descricao:',
    desc.slice(0, 3500)
  ].join(NL);

  out.push({
    json: {
      jobId: String(j.jobId),
      title: String(j.title || ''),
      url: String(j.url || ''),
      jobType: String(j.jobType || ''),
      orcamento: orcamento,
      valorEstimado: fixo !== null ? fixo : (hmax || null),
      idadeMin: idade,
      totalApplicants: appl,
      clientCountry: String(j.clientCountry || ''),
      clientPaymentVerified: !!j.clientPaymentVerified,
      clientTotalSpent: Number(j.clientTotalSpent || 0),
      clientRating: Number(j.clientRating || 0),
      description: desc.slice(0, 3500),
      promptScore: RUBRICA.split('{{limiar}}').join(String(LIMIAR)).split('{{vaga}}').join(vaga)
    }
  });
}

console.log('pre-filtro: ' + out.length + ' passaram, ' + cortadas.length + ' cortadas');
for (const c of cortadas) { console.log('  CORTA: ' + String(c.title).slice(0, 50) + ' | ' + c.motivo); }

return out;

// So segue quem ainda nao esta no Notion (evita alerta duplicado no Telegram).
const out = [];
const itens = $input.all();
for (let i = 0; i < itens.length; i++) {
  const dedup = itens[i].json || {};
  const existe = Array.isArray(dedup.results) && dedup.results.length > 0;
  const vaga = $('Pre-filtro + Monta Prompt Score').all()[i].json;
  if (existe) {
    console.log('DUP ignorada: ' + String(vaga.title).slice(0, 50));
    continue;
  }
  out.push({ json: vaga });
}
console.log('ineditas: ' + out.length + ' de ' + itens.length);
return out;

// gotcha #2: modelos com thinking devolvem bloco 'thinking' antes do 'text'.
// gotcha (novo, 24/07): max_tokens baixo truncava o JSON -> agora 2500 e checagem explicita.
const NL = String.fromCharCode(10);
const out = [];
const itens = $input.all();

for (let i = 0; i < itens.length; i++) {
  const resp = itens[i].json || {};
  const vaga = $('Filtra Ineditas').all()[i].json;

  const blocos = Array.isArray(resp.content) ? resp.content : [];
  const tb = blocos.find(function (c) { return c && c.type === 'text'; });
  if (!tb) {
    console.log('ERRO sem bloco text | stop=' + String(resp.stop_reason) + ' | ' + String(vaga.title).slice(0, 40));
    continue;
  }

  let raw = String(tb.text || '').trim();
  const ini = raw.indexOf('{');
  const fim = raw.lastIndexOf('}');
  if (ini === -1 || fim === -1) {
    console.log('ERRO sem JSON no texto | ' + String(vaga.title).slice(0, 40));
    continue;
  }
  raw = raw.slice(ini, fim + 1);

  let s;
  try { s = JSON.parse(raw); }
  catch (e) {
    console.log('ERRO JSON invalido (' + e.message + ') | stop=' + String(resp.stop_reason) + ' | ' + String(vaga.title).slice(0, 40));
    continue;
  }

  const aplica = s.recommendation === 'apply' && Number(s.score) >= 7;

  const PERFIL_PROP = [
    'n8n self-hosted em Docker com 7 workflows em producao (nao protótipos).',
    'Pipeline de prospeccao B2B ponta a ponta: cron -> scraping -> auditoria tecnica automatica do site -> descoberta de email -> LLM classifica o problema e escreve a abordagem -> envio transacional -> CRM, com deduplicacao e ramp de aquecimento de dominio.',
    'Workflow de gestao de respostas: Gmail trigger -> casa remetente contra CRM -> LLM classifica a resposta -> ramifica para rascunho de proposta, atualizacao de status, ou escalonamento humano.',
    'Webhooks de pagamento (Stripe HMAC-SHA256, PayPal verify-webhook-signature) com verificacao de assinatura real, testada contra payload forjado e genuino.',
    'Notion API como CRM programatico, Gmail API/OAuth2, Brevo com dominio autenticado (SPF/DKIM), Apify, PageSpeed API.',
    'Trabalha em mercado com regulacao pesada (GDPR/UWG) - sabe onde a automacao precisa parar e passar pro humano.',
    'Entrega por repositorio GitHub ou arquivo. Comunicacao por texto.'
  ].join(NL);

  const promptProposta = [
    'Voce e um engenheiro de automacao escrevendo uma proposta para uma vaga no Upwork.',
    '',
    'REGRAS:',
    '- 150 a 220 palavras. Ingles.',
    '- A PRIMEIRA FRASE deve ser esta observacao concreta sobre o problema do cliente, reescrita naturalmente: "' + String(s.angle || '') + '"',
    '- Nunca mencione IA, Claude, ChatGPT, LLM ou qualquer ferramenta usada para escrever a proposta.',
    '- Proponha 3 passos concretos de execucao, especificos desta vaga (nao generico).',
    '- Cite experiencia relevante SOMENTE do que esta no perfil abaixo. Nao invente nada.',
    '- Nao use: "I am the perfect fit", "I have read your job description carefully", "I am excited", "Dear Hiring Manager", "utilize", "leverage", "seamless", "robust solution", "cutting-edge".',
    '- Nao abra com "I". Nao use bullet com emoji.',
    '- Frases curtas. Tom de par tecnico conversando com par, nao vendedor.',
    '- Termine com UMA pergunta especifica sobre uma decisao tecnica da vaga.',
    '- Sem assinatura, sem "Best regards".',
    '',
    'Escopo estimado internamente: ' + String(s.complexity) + ', ~' + String(s.estimated_hours) + 'h. Use isso para dar prazo realista, mas nao mencione horas.',
    '',
    '## Perfil (fatos verificaveis - nao extrapole)',
    PERFIL_PROP,
    '',
    '## Vaga',
    'Titulo: ' + vaga.title,
    'Orcamento: ' + vaga.orcamento,
    'Descricao:',
    String(vaga.description).slice(0, 3000),
    '',
    'Responda somente com o texto da proposta.'
  ].join(NL);

  out.push({
    json: Object.assign({}, vaga, {
      score: Number(s.score),
      recommendation: s.recommendation,
      complexity: s.complexity,
      estimated_hours: Number(s.estimated_hours || 0),
      budget_realistic: !!s.budget_realistic,
      red_flags: Array.isArray(s.red_flags) ? s.red_flags : [],
      why: String(s.why || ''),
      angle: String(s.angle || ''),
      aplica: aplica,
      promptProposta: promptProposta
    })
  });
}

return out;

const NL = String.fromCharCode(10);
const out = [];
const itens = $input.all();

for (let i = 0; i < itens.length; i++) {
  const resp = itens[i].json || {};
  const v = $('IF score >= 7').all()[i].json;

  const blocos = Array.isArray(resp.content) ? resp.content : [];
  const tb = blocos.find(function (c) { return c && c.type === 'text'; });
  const proposta = tb ? String(tb.text || '').trim() : '(FALHA ao gerar proposta - escreva manualmente)';

  const notionBody = {
    parent: { database_id: '3a78b3ec-a1b8-810f-ac9f-ff3ec411949d' },
    properties: {
      'Nome da vaga': { title: [{ text: { content: v.title.slice(0, 1900) } }] },
      'Job ID': { rich_text: [{ text: { content: v.jobId } }] },
      'Plataforma': { select: { name: 'Upwork' } },
      'Data de captura': { date: { start: new Date().toISOString() } },
      'Score': { number: v.score },
      'Status': { select: { name: 'Qualificada' } },
      'Orcamento': { rich_text: [{ text: { content: v.orcamento } }] },
      'Link da vaga': { url: v.url },
      'Proposta enviada': { rich_text: [{ text: { content: proposta.slice(0, 1900) } }] },
      'Pagamento verificado': { checkbox: v.clientPaymentVerified },
      'Pais do cliente': { rich_text: [{ text: { content: v.clientCountry } }] },
      'Cliente gastou USD': { number: v.clientTotalSpent },
      'Propostas': { number: v.totalApplicants },
      'Complexidade': { select: { name: v.complexity } },
      'Horas estimadas': { number: v.estimated_hours },
      'Red flags': { rich_text: [{ text: { content: (v.red_flags.join('; ') || 'nenhuma').slice(0, 1900) } }] },
      'Recomendacao': { select: { name: 'apply' } }
    }
  };
  if (v.valorEstimado) { notionBody.properties['Valor estimado USD'] = { number: v.valorEstimado }; }

  const alerta = [
    'VAGA ' + v.score + '/10 - ' + v.idadeMin + 'min - ' + v.totalApplicants + ' propostas',
    '',
    v.title,
    v.orcamento + ' | ' + v.complexity + ' | ~' + v.estimated_hours + 'h',
    'Cliente: ' + v.clientCountry + ' | gastou $' + v.clientTotalSpent + ' | rating ' + v.clientRating,
    (v.red_flags.length ? 'FLAGS: ' + v.red_flags.join('; ') : 'sem red flags'),
    '',
    v.url,
    '',
    '--- PROPOSTA (copiar) ---',
    proposta
  ].join(NL);

  out.push({ json: { notionBody: notionBody, alerta: alerta.slice(0, 4000), title: v.title, url: v.url } });
}

return out;

// Vagas reprovadas tambem vao pro Notion: e isso que permite calibrar a rubrica depois.
const out = [];
for (const item of $input.all()) {
  const v = item.json;
  const body = {
    parent: { database_id: '3a78b3ec-a1b8-810f-ac9f-ff3ec411949d' },
    properties: {
      'Nome da vaga': { title: [{ text: { content: String(v.title).slice(0, 1900) } }] },
      'Job ID': { rich_text: [{ text: { content: String(v.jobId) } }] },
      'Plataforma': { select: { name: 'Upwork' } },
      'Data de captura': { date: { start: new Date().toISOString() } },
      'Score': { number: Number(v.score || 0) },
      'Status': { select: { name: 'Arquivada' } },
      'Orcamento': { rich_text: [{ text: { content: String(v.orcamento) } }] },
      'Link da vaga': { url: String(v.url) },
      'Pagamento verificado': { checkbox: !!v.clientPaymentVerified },
      'Pais do cliente': { rich_text: [{ text: { content: String(v.clientCountry) } }] },
      'Cliente gastou USD': { number: Number(v.clientTotalSpent || 0) },
      'Propostas': { number: Number(v.totalApplicants || 0) },
      'Complexidade': { select: { name: String(v.complexity || 'medium') } },
      'Horas estimadas': { number: Number(v.estimated_hours || 0) },
      'Red flags': { rich_text: [{ text: { content: String((v.red_flags || []).join('; ') + ' | ' + v.why).slice(0, 1900) } }] },
      'Recomendacao': { select: { name: 'skip' } }
    }
  };
  out.push({ json: { notionBody: body } });
}
return out;
